@Service
@RequiredArgsConstructor
public class OrderService {
    private final OrderMapper orderMapper;
    private final OrderService self;        // 注入自身代理（或拆到另一个 Bean）

    public void placeOrder(Order o) {
        // this.save(o);  // ❌ 自调用，不走代理，事务失效
        self.save(o);     // ✅ 走代理
    }

    @Transactional(rollbackFor = Exception.class)
    public void save(Order o) throws Exception {
        orderMapper.insert(o);
        if (o.getAmount() == null) {
            throw new Exception("金额为空");  // 受检异常，配了 rollbackFor 才回滚
        }
    }
}
// 注：注入自身需 @Lazy 或允许循环引用；更推荐把事务方法拆到独立 Bean。

@Component
public class DemoBean implements BeanNameAware, InitializingBean, DisposableBean {
    public DemoBean() { System.out.println("1 构造/实例化"); }

    @Autowired
    public void setEnv(Environment env) { System.out.println("2 属性注入"); }

    @Override public void setBeanName(String name) { System.out.println("3 Aware: " + name); }

    @PostConstruct public void post() { System.out.println("4 @PostConstruct"); }

    @Override public void afterPropertiesSet() { System.out.println("5 afterPropertiesSet"); }

    @PreDestroy public void pre() { System.out.println("7 @PreDestroy"); }

    @Override public void destroy() { System.out.println("8 DisposableBean.destroy"); }
}

@Component
class LogProcessor implements BeanPostProcessor {
    @Override
    public Object postProcessAfterInitialization(Object bean, String name) {
        if (bean instanceof DemoBean) System.out.println("6 BPP after（AOP 代理在此类处理器中生成）");
        return bean;
    }
}

// 自定义 starter：短信客户端自动配置
@AutoConfiguration
@ConditionalOnClass(SmsClient.class)
@EnableConfigurationProperties(SmsProperties.class)
public class SmsAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean                       // 用户自己定义了就不覆盖
    @ConditionalOnProperty(prefix = "sms", name = "enabled", havingValue = "true", matchIfMissing = true)
    public SmsClient smsClient(SmsProperties props) {
        return new SmsClient(props.getEndpoint(), props.getAppKey());
    }
}

@ConfigurationProperties(prefix = "sms")
public record SmsProperties(String endpoint, String appKey, boolean enabled) {}

